// 同一原轮次副本的军级一次震动；纯域不假称已验Common死亡或完整World回放。
#include "resident/domains/military/military_command_shock.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;void check(bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);}template<class T>T take(Outcome<T> r){if(!r.ok)throw std::runtime_error(r.error.original.code);return std::move(r.value);}
MilitaryBattleRecord frame(){MilitaryBattleRecord b;b.id="battle:10";b.battlefield_id="field";b.round=2;for(Integer i=0;i<4;++i){BattleUnit u;u.unit_id="u"+std::to_string(i);u.army_id=i<2?"a":i==2?"b":"c";u.commander_actor_id="p"+std::to_string(i);u.troop_type_id="foot";u.side=i<3?0:1;u.position={i,0};u.morale=60;u.fit=u.member_ids={"soldier:"+u.unit_id};b.units.push_back(u);}return b;}
MilitaryCommandShockState state(){MilitaryCommandShockState s;for(const auto& pair:std::vector<std::pair<StableId,Integer>>{{"a",0},{"b",2},{"c",3}})s.leaders.push_back({pair.first,"p"+std::to_string(pair.second),"u"+std::to_string(pair.second),{MilitaryFieldCommandSourceKind::army_formation,"action:"+std::to_string(pair.second+1)},{},{}});return s;}
MilitaryBattleCatalog catalog(){MilitaryBattleCatalog c;BattlefieldDefinition f;f.id="field";f.exits={{0,{0,0},{}},{1,{3,0},{}}};c.battlefields={f};return c;}
}
int main(){try{auto b=frame(),after=b;auto s=state();auto c=catalog();MilitaryCommandShockRule rule;after.units[0].statuses={{"military_commander_loss_v1",2}};auto killed=take(resolve_military_command_shock(b,after,{},c,rule,s));check(killed.state.causes.size()==1&&killed.state.causes[0].actor_id=="p0"&&killed.state.causes[0].kind=="commander_killed","exact military army commander death triggers one cause");check(killed.battle.units[1].morale==50&&killed.battle.units[2].morale==60&&killed.battle.units[3].morale==60,"only original army feels loss, not same-side allies or opponent");check(killed.battle.units[0].fit==b.units[0].fit&&killed.battle.units[1].member_ids==b.units[1].member_ids&&killed.battle.rng_state==b.rng_state,"no soldier mint, casualty or extra RNG");auto later=killed.battle;++later.round;auto repeated=take(resolve_military_command_shock(later,later,{},c,rule,killed.state));check(repeated.state.causes.size()==1&&repeated.battle.units[1].morale==50&&repeated.events.empty(),"same commander cannot shake army twice");
 after=b;after.units[1].statuses={{"military_commander_loss_v1",2}};check(take(resolve_military_command_shock(b,after,{},c,rule,s)).state.causes.empty(),"ordinary unit captain is not army commander");after=b;after.units[0].morale=0;after.units[1].morale=5;auto routed=take(resolve_military_command_shock(b,after,{},c,rule,s));check(routed.battle.units[1].morale==0&&routed.state.causes[0].kind=="unit_routed","actual commander rout can begin later original rout classification");
 MilitaryOrders withdraw{{"u0",{"withdraw",{0,0},0,{},{},{}}}};auto left=take(resolve_military_command_shock(b,b,withdraw,c,rule,s));check(left.state.causes.size()==1&&left.state.causes[0].kind=="unit_withdrawn"&&left.battle.units[0].morale==60&&left.battle.units[1].morale==50,"real accepted withdrawal at own exit is one source and remains executable");auto away=b;away.units[0].position={1,0};check(take(resolve_military_command_shock(away,away,withdraw,c,rule,s)).state.causes.empty(),"unreached declared exit is not a completed retreat");auto absent=s;absent.leaders[0].actor_id="remote";absent.leaders[0].unit_id.clear();after=b;after.units[0].morale=0;check(take(resolve_military_command_shock(b,after,{},c,rule,absent)).state.causes.empty(),"no invented death or retreat for off-board commander");auto bad=s;bad.leaders[0].unit_id="u1";check(!resolve_military_command_shock(b,b,{},c,rule,bad).ok,"forged binding rejected");bad=s;bad.causes={{"a","p0","u0","commander_killed",2,{}}};check(!resolve_military_command_shock(b,b,{},c,rule,bad).ok,"this round cannot claim a preexisting cause");after=b;after.units[0].morale=0;check(!resolve_military_command_shock(after,after,{},c,rule,s).ok,"prior defeated commander needs real previous cause");
 std::cout<<"MILITARY_COMMAND_SHOCK="<<checks<<" FAILURES=0 SCOPE=PURE_ROUND_COMPONENT\n";return 0;}catch(const std::exception& e){std::cerr<<"MILITARY_COMMAND_SHOCK_FAIL "<<checks<<" "<<e.what()<<'\n';return 1;}}
